CREATE TABLE IF NOT EXISTS rental_source_bindings (namespace VARCHAR(150) NOT NULL, collection VARCHAR(150) NOT NULL, source_id VARCHAR(180) NOT NULL, entity_type VARCHAR(40) NOT NULL, entity_id BIGINT NOT NULL, relation_kind VARCHAR(60) NOT NULL, evidence_json JSON NOT NULL, mapping_hash CHAR(64) NOT NULL, PRIMARY KEY(namespace,collection,source_id,entity_type,entity_id,relation_kind));
CREATE TABLE IF NOT EXISTS rental_import_validations (state_hash CHAR(64) NOT NULL, mapping_hash CHAR(64) NOT NULL, validator_version INT NOT NULL, report_json JSON NOT NULL, validated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(state_hash,mapping_hash,validator_version));
